  border-bottom: none !important;
  border-left: none !important;
  border-right: none !important;
  min-height: var(--chat-bottom-height) !important;
  box-shadow: none !important;
  position: relative !important;
}

.input-action-bar-custom,
.input-row-wrapper {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* ========================================= 输入框本体 ========================================= */
textarea.input-box-custom,
.input-box-custom {
  width: var(--input-box-width) !important;
  height: var(--input-box-height) !important;
  min-height: var(--input-box-height) !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  box-shadow: inset 0 0 0 9999px #ffffff !important;
  border-radius: 6px !important;
  border: none !important;
  position: absolute !important;
  top: var(--input-box-top) !important;
  left: var(--input-box-left) !important;
  padding: 8px 36px 8px 10px !important;
  color: var(--input-text-color) !important;
  -webkit-text-fill-color: var(--input-text-color) !important;
  font-size: 15px !important;
  box-sizing: border-box !important;
  z-index: 20 !important;
}

textarea.input-box-custom::placeholder,
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

/* ========================================= 独立按钮替换与排版 (已修复菜单消失) ========================================= */

/* 1. 语音按钮 */
.input-btn-mic svg {
  display: none !important;
}
.input-btn-mic {
  width: var(--mic-width) !important;
  height: var(--mic-height) !important;
  position: absolute !important;
  top: var(--mic-top) !important;
  right: var(--mic-right) !important;
  background-image: url("https://i.postimg.cc/mgSGPfQy/无标题183_20260222183226.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 30 !important;
  transform: scale(0.6) !important;
  opacity: 1 !important; /* 强制显示 */
  display: block !important;
}

/* 2. 表情按钮 */
