  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  z-index: 60 !important;
  opacity: 1 !important; /* 洗掉 icity 里的 opacity:0 */
  visibility: visible !important;
  display: block !important;
}

/* 4. 等待回复 (AI) 按钮 */
.input-btn-ai svg {
  display: none !important;
}
.input-btn-ai {
  width: var(--ai-width) !important;
  height: var(--ai-height) !important;
  min-width: var(--ai-width) !important;
  position: absolute !important;
  top: var(--ai-top) !important;
  left: var(--ai-left) !important;
  background-image: url("https://i.postimg.cc/cLcNvyQn/无标题183_20260222183221.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  opacity: 1 !important;
  z-index: 51 !important;
  transition: opacity 0.2s !important;
  display: block !important;
}

/* 5. 发送按钮 */
.send-btn-custom svg {
  display: none !important;
}
.send-btn-custom {
  width: var(--send-width) !important;
  height: var(--send-height) !important;
  min-width: var(--send-width) !important;
  position: absolute !important;
  top: var(--send-top) !important;
  left: var(--send-left) !important;
  background-image: url("https://i.postimg.cc/7h4RCvXH/wu-biao-ti278-20260320120134.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  z-index: 50 !important;
  opacity: 1 !important;
  display: block !important;
}

/* 打字时 发送键左侧装饰图 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  content: "" !important;
  position: absolute !important;
  width: var(--dec-width) !important;
  height: var(--dec-height) !important;
  top: var(--dec-top) !important;
  left: var(--dec-left) !important;
  background-image: url("https://i.postimg.cc/yNYC9QPg/无标题183_20260222183223.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none !important;
  z-index: 40 !important;
}

/* 防卡死补丁 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))
  .input-btn-ai {
  opacity: 0 !important;
  pointer-events: none !important;
}
.more-options-popup {
  z-index: 999999 !important;
}
.input-area-custom:has(.more-options-popup) .input-btn-ai,
.input-area-custom:has(.more-options-popup) .input-btn-plus,
.input-area-custom:has(.more-options-popup) .input-btn-sticker,
.input-area-custom:has(.more-options-popup) .input-btn-mic,
.input-area-custom:has(.more-options-popup) .send-btn-custom {
  pointer-events: none !important;
}

/* ========================================= 【修正】系统时间、系统提示框 (解决太长的问题) ========================================= */
.timestamp-custom,
.date-divider-custom,
.system-message-custom,
[class*="system-message"],
[class*="timestamp"],
[class*="date-divider"] {
  width: fit-content !important; /* 像微信一样紧贴文字宽度 */
  max-width: 80% !important;
  margin: 8px auto !important; /* 绝对居中 */

  background-color: #fcfcfc !important;
  border: 0.6px solid #e3e3e3 !important;
  color: #727272 !important;
  border-radius: 6px !important;
  padding: 2px 10px !important;

  display: block !important;
  text-align: center !important;
  box-sizing: border-box !important;
  font-size: 12px !important;
}
/* ========================================= 【可直接调整区】气泡小角 (带弧度三角) 设置 ========================================= */
:root {
  /* --- 我方气泡小角 (右侧绿色) --- */
  --me-tail-size: 9px; /* 决定小角的整体大小 */
  --me-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --me-tail-top: 14px; /* 上下位置 */
  --me-tail-right: -4px; /* 左右位置 (负数代表往气泡外面移) */

  /* --- AI气泡小角 (左侧白色) --- */
  --them-tail-size: 9px; /* 决定小角的整体大小 */
  --them-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --them-tail-top: 14px; /* 上下位置 */
  --them-tail-left: -4px; /* 左右位置 (负数代表往气泡外面移) */
}

/* ========================================= 1. 我方气泡 (绿色) ========================================= */
.bubble-me-custom {
  background-color: #95ec69 !important;
  background: #95ec69 !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important; /* 必须开启，允许小角溢出 */
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important; /* 建立层级，防止小角被背景吞掉 */
}

/* 强制我方气泡连发时不改变圆角 */
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  border-radius: 4px !important;
}

/* 强制我方气泡内的文字颜色 */
.bubble-me-custom,
.bubble-me-custom * {
  color: #0f180a !important;
}

/* 我方气泡右侧小角 (带弧度的旋转正方形实现) */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  top: var(--me-tail-top) !important;
  right: var(--me-tail-right) !important;
  width: var(--me-tail-size) !important;
  height: var(--me-tail-size) !important;
  background-color: #95ec69 !important;

  /* 核心：倒角4px，并旋转45度，让右上角变成向右指的圆润尖角 */
  border-radius: var(--me-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}

/* ========================================= 2. AI / 对方气泡 (白色) ========================================= */
.bubble-them-custom {
  background-color: #ffffff !important;
  background: #ffffff !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important;
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important;
}

/* 强制对方气泡连发时不改变圆角 */
.bubble-them-custom.first,
.bubble-them-custom.mid,
.bubble-them-custom.last {
  border-radius: 4px !important;
}

/* 强制对方气泡内的文字颜色 */
.bubble-them-custom,
.bubble-them-custom * {
  color: #1a1a1a !important;
}

/* AI气泡左侧小角 (带弧度的旋转正方形实现) */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  top: var(--them-tail-top) !important;
  left: var(--them-tail-left) !important;
  width: var(--them-tail-size) !important;
  height: var(--them-tail-size) !important;
  background-color: #ffffff !important;

  /* 核心：倒角4px，并旋转45度，让左下角变成向左指的圆润尖角 */
  border-radius: var(--them-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}
/* ========================================= 3. 特殊消息自动隐藏气泡与小角 (表情包/图片/转账等) ========================================= */

/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ),
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 强制隐藏我方特殊消息的气泡小角 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::after {
  display: none !important;
}

/* 强制隐藏对方特殊消息的气泡小角 */
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::before {
  display: none !important;
}

