  display: none !important;
}
.send-btn-custom {
  width: var(--send-width) !important;
  height: var(--send-height) !important;
  min-width: var(--send-width) !important;
  position: absolute !important;
  top: var(--send-top) !important;
  left: var(--send-left) !important;
  background-image: url("https://i.postimg.cc/7h4RCvXH/wu-biao-ti278-20260320120134.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  z-index: 50 !important;
  opacity: 1 !important;
  display: block !important;
