.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 强制隐藏我方特殊消息的气泡小角 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::after {
  display: none !important;
}

/* 强制隐藏对方特殊消息的气泡小角 */
.bubble-them-custom:has(
